    public static String[] langs() { return new String[]{"de", "en", "es", "it", "pt"}; }

    public static String po(String lang) {
        switch (lang) {
            case "de": return c_po_de();
            case "en": return c_po_en();
            case "es": return c_po_es();
            case "it": return c_po_it();
            case "pt": return c_po_pt();
            default: return null;
        }
    }
